"""Organizer-run replay: the yudduy (#227) 32-step collision pair follows the Fig. 6 characteristic (Li, Liu, Wang,
Shi, CRYPTO 2026) step by step after a C_32 first block. Every trial returns the same committed pair; the organizer
checks the full-collision event. Observations count Fig. 6 signed-row mismatches (A, E steps -4..22; W 0..31) of the
second block from CV1 = C_32(IV, M0), which must be 0. This tests the truncated route on one pair only; it makes no
claim about attack cost or success rates."""
import json, struct, sys
M = 0xFFFFFFFF
K = [0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
     0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
     0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
     0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967]
IV = [0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19]
MSG_A = "04a9b33e6ea679aa89f6fb3bf530dfa8c5828a5e385388a40dbcd14f77252e334fef2ad0809de1a4a3b955b63a95b0cc5cadb08001a17ef200000000801aecede37cab305f4048fd95caa0fc87591d98fb8464a3399cc8f36c91c8c47d608f344ee3725258e49d8210746273a96ce15445f2222c4d12f88ad2701ece17d9748f"
MSG_B = "04a9b33e6ea679aa89f6fb3bf530dfa8c5828a5e385388a40dbcd14f77252e334fef2ad0809de1a4a3b955b63a95b0cc5cadb08001a17ef200000000801aecede37cab305f4048fd95caa0fc87591d98db8464a33ddcc0f34c91c8c47c619fbe4eeb7e5258e49d8210746273a96ce15441b22a2c6d12f88ad2701ece17d9748f"
FIG6_A = ["================================","================================","================================","================================","================================","================================","================================","================================","==n=============================","=====n===n===n=u====n===u==u====","================================","================================","================================","==========u====================u","================================","====n=========u=u=======u==n====","=un===u=n=======n===============","================================","==u=============================","================================","================================","================================","================================","================================","================================","================================","================================"]
FIG6_E = ["================================","================================","================================","================================","================================","================================","================================","================================","==n=============================","=====u===n=nuu======n======u====","===n=======n======n=u===n==n=n=u","==u============n================","uuu=============================","=====n=nuuu==n=u====n===u==u=unn","un===================u=u========","====n=========u=u=======u=nu====","===uuu==uuuuuuuu==n====n=uuu====","=n====uu=n=====u=u==nnn========n","================================","=============u=============n====","======u=n=======n===============","================================","==u=============================","================================","================================","================================","================================"]
FIG6_W = ["================================","================================","================================","================================","==n=============================","=====u===u==========n===========","==n=============================","=======n=======u===u====u===u=u=","============u=======uu==========","================================","================================","================================","=====n===n==========u===========","==u=============================","================================","================================","================================","================================","================================","================================","=======nn=======u===============","================================","==n=============================","================================","================================","================================","================================","================================","================================","================================","================================","================================"]
R = lambda x, n: ((x >> n) | (x << (32 - n))) & M
S0 = lambda x: R(x, 2) ^ R(x, 13) ^ R(x, 22)
S1 = lambda x: R(x, 6) ^ R(x, 11) ^ R(x, 25)
s0 = lambda x: R(x, 7) ^ R(x, 18) ^ (x >> 3)
s1 = lambda x: R(x, 17) ^ R(x, 19) ^ (x >> 10)
IF = lambda x, y, z: (x & y) ^ (~x & M & z)
MAJ = lambda x, y, z: (x & y) ^ (x & z) ^ (y & z)


def trace(cv, m):
    w = list(m)
    for i in range(16, 32):
        w.append((s1(w[i - 2]) + w[i - 7] + s0(w[i - 15]) + w[i - 16]) & M)
    A = {-1: cv[0], -2: cv[1], -3: cv[2], -4: cv[3]}; E = {-1: cv[4], -2: cv[5], -3: cv[6], -4: cv[7]}
    for i in range(32):
        E[i] = (A[i - 4] + E[i - 4] + S1(E[i - 1]) + IF(E[i - 1], E[i - 2], E[i - 3]) + K[i] + w[i]) & M
        A[i] = (E[i] - A[i - 4] + S0(A[i - 1]) + MAJ(A[i - 1], A[i - 2], A[i - 3])) & M
    out = [A[31], A[30], A[29], A[28], E[31], E[30], E[29], E[28]]
    return A, E, w, [(a + b) & M for a, b in zip(cv, out)]


def signed(x, xp):
    return "".join("=" if ((x >> j) & 1) == ((xp >> j) & 1) else ("n" if not (x >> j) & 1 else "u") for j in range(31, -1, -1))


def main():
    req = json.loads(sys.stdin.read())
    a, b = bytes.fromhex(MSG_A), bytes.fromhex(MSG_B)
    wa, wb = struct.unpack(">32I", a), struct.unpack(">32I", b)
    _, _, _, cv1 = trace(IV, wa[:16])
    Ax, Ex, Wx, h1 = trace(cv1, wb[16:])        # unprimed = message B
    Ap, Ep, Wp, h2 = trace(cv1, wa[16:])
    mis = sum(signed(Ax[i], Ap[i]) != FIG6_A[i + 4] for i in range(-4, 23))
    mis += sum(signed(Ex[i], Ep[i]) != FIG6_E[i + 4] for i in range(-4, 23))
    mis += sum(signed(Wx[i], Wp[i]) != FIG6_W[i] for i in range(32))
    obs = {"fig6_rows_checked": 86, "fig6_row_mismatches": mis, "second_block_cv_equal": int(h1 == h2),
           "shared_first_block": int(wa[:16] == wb[:16])}
    trials = [{"trial": t["trial"], "message_a_hex": a.hex(), "message_b_hex": b.hex(), "observations": obs}
              for t in req["trials"]]
    sys.stdout.write(json.dumps({"schema_version": 1, "trials": trials}))


main()
